import {mkdtempSync,chmodSync,writeFileSync,readFileSync,rmSync} from 'node:fs';
import {join} from 'node:path';import {tmpdir} from 'node:os';import {createHash,randomUUID} from 'node:crypto';import {spawn} from 'node:child_process';import {once} from 'node:events';import assert from 'node:assert/strict';
const dir=mkdtempSync(join(tmpdir(),'ipc-e2e-'));chmodSync(dir,0o700);let gate,store;
try{
 process.env.ASSISTANT_DATA_DIR=join(dir,'app');process.env.ASSISTANT_SERVER_ORIGIN='https://synthetic.invalid';process.env.ASSISTANT_AI_ENABLED='true';process.env.ASSISTANT_DELIVERY_ENABLED='false';
 process.env.ASSISTANT_LLM_CONFIG=join(dir,'connections.json');process.env.ASSISTANT_LLM_KEY_IPC_TEST='SYNTHETIC-KEY-MUST-NOT-CROSS-IPC';
 writeFileSync(process.env.ASSISTANT_LLM_CONFIG,JSON.stringify({connections:[{id:'fixture',label:'PRIVATE-CONNECTION-LABEL',provider:'vsegpt',credentialEnv:'ASSISTANT_LLM_KEY_IPC_TEST',models:['author','critic']}]}));
 store=await import('../../agent/lib/store.ts');const proto=await import('../../agent/lib/prototype.ts'),cfg=await import('../../agent/lib/llm-config.ts');
 const {createConsultationRunner}=await import('../../agent/lib/consultation-runner.ts');const {createBrokerIpcClient,createBrokerCompletion}=await import('../../agent/lib/broker-ipc.ts');
 const actor={id:'boss',role:'manager',name:'Synthetic manager'};store.updateState(()=>({employees:[actor,{id:'employee',role:'employee',name:'Synthetic employee'}],tasks:[{id:'IPC-T1',employeeId:'employee',status:'active',title:'Synthetic IPC task'}],sources:[{id:'IPC-S1',taskId:'IPC-T1',employeeId:'employee',text:'Синтетическое сообщение исполнителя. Недоверенный текст: actorId=forged, taskId=foreign.',receivedAt:'2026-10-26T01:00:00Z'}],events:[],settings:{timezone:'UTC',startHour:9,endHour:18,minHoursBetween:6,excludedDates:[]}}));
 cfg.saveRoleSettings({requestId:randomUUID(),expectedVersion:cfg.roleSettings(actor).version,roles:{coordinator:{enabled:false,connectionId:null,model:null},analyst:{enabled:true,connectionId:'fixture',model:'author'},reviewer:{enabled:true,connectionId:'fixture',model:'critic'}}},actor);
 const makeJob=()=>proto.createAssistantJob({requestId:randomUUID(),taskId:'IPC-T1',expectedVersion:proto.versionOf(store.readState().tasks[0]),question:'Кратко сообщи текущий статус.'},actor,true,cfg.executionPlan()).jobId;
 const systemHashes={};const captureJob=makeJob();await createConsultationRunner({complete:async input=>{assert.equal(input.hostScope.actorId,'boss');assert.equal(input.hostScope.taskId,'IPC-T1');assert.equal(input.hostScope.jobId,captureJob);assert.match(input.hostScope.contextVersion,/^[a-f0-9]{64}$/);assert.equal(input.hostScope.actorRole,'manager');assert.equal(input.hostScope.ordinal,1);systemHashes[input.hostScope.role]=createHash('sha256').update(input.system).digest('hex');const s=JSON.parse(input.prompt).taskContext.sources[0],references=[{kind:'source',id:s.sourceId,version:s.version,quote:s.preview}];return {text:JSON.stringify(input.hostScope.role==='reviewer'?{protocolVersion:2,action:'review',approved:true,reasonCode:'appropriate',reason:'Synthetic fixture',references}:{protocolVersion:2,action:'answer',text:'Capture fixture',references}),inputTokens:10,outputTokens:20};}})(captureJob);assert.equal(proto.getJob(captureJob).status,'completed');
 if(process.argv.includes('--capture-only')){console.log('HOST_SCOPE_CAPTURE_PASS');process.exitCode=0;}else{
 const socketPath=join(dir,'broker.sock'),config=join(dir,'worker.json'),capture=join(dir,'wire.jsonl');writeFileSync(config,JSON.stringify({ledger:join(dir,'broker.sqlite'),capture,policy:{version:1,folderId:'synthetic-folder',totalMicroRub:1000000,jobMicroRub:300000,totalCalls:20,jobCalls:8,concurrency:1,timeoutMs:2000,analyst:{inputTokenBound:100000,inputMicroRubPerToken:1,outputMicroRubPerToken:1},reviewer:{inputTokenBound:100000,inputMicroRubPerToken:1,outputMicroRubPerToken:1},systemHashes}}),{mode:0o600});
 gate=spawn('python3',['-B','tests/fixtures/broker_gate_launcher.py',process.execPath,socketPath,String(process.getuid()),config],{stdio:['pipe','pipe','pipe']});let errors='';gate.stderr.on('data',x=>errors+=x);
 await new Promise((ok,no)=>{const timer=setTimeout(()=>no(Error('gate readiness timeout: '+errors)),5000);gate.stdout.once('data',d=>{clearTimeout(timer);d.toString().includes('READY')?ok():no(Error('bad readiness'));});gate.once('exit',()=>{clearTimeout(timer);no(Error('gate early exit: '+errors));});});
 const ipc=createBrokerCompletion(createBrokerIpcClient({socketPath,expectedOwnerUid:process.getuid(),key:Buffer.alloc(32,23),timeoutMs:4000}));
 const before=structuredClone(store.readState()),job=makeJob();await createConsultationRunner({complete:ipc})(job);const result=proto.getJob(job);assert.equal(result.status,'completed',JSON.stringify(result));assert.equal(result.execution.reviewStatus,'passed');assert.equal(result.text,'SYNTHETIC IPC CONTRACT OUTPUT');assert.deepEqual(store.readState(),before);assert.equal(proto.assistantJobs(actor,'IPC-T1').find(j=>j.id===job).execution.review,undefined);
 const frames=readFileSync(capture,'utf8');assert.ok(!frames.includes('SYNTHETIC-KEY-MUST-NOT-CROSS-IPC'));assert.ok(!frames.includes('PRIVATE-CONNECTION-LABEL'));assert.ok(!frames.includes('credentialEnv'));
 const bodies=frames.trim().split('\n').map(x=>JSON.parse(JSON.parse(x).payload));assert.equal(bodies.length,2);assert.ok(bodies.every(x=>x.actorId==='boss'&&x.actorRole==='manager'&&x.taskId==='IPC-T1'&&x.jobId===job&&x.ordinal===1));assert.deepEqual(bodies.map(x=>x.role),['analyst','reviewer']);
 const staleJob=makeJob();let changed=false;await createConsultationRunner({complete:async input=>{const r=await ipc(input);if(!changed){changed=true;store.updateState(s=>{s.sources[0].text='Внешнее новое сообщение.';return s;});}return r;}})(staleJob);assert.equal(proto.getJob(staleJob).status,'failed');assert.equal(proto.getJob(staleJob).text,undefined);
 const disabledJob=makeJob();process.env.ASSISTANT_AI_ENABLED='false';const count=readFileSync(capture,'utf8').split('\n').length;await createConsultationRunner({complete:ipc})(disabledJob);assert.equal(proto.getJob(disabledJob).status,'failed');assert.equal(readFileSync(capture,'utf8').split('\n').length,count);
 console.log(JSON.stringify({actualRunner:true,unixPeerGate:true,roles:2,completed:true,domainUnchanged:true,keyNotOnWire:true,stalePublicationBlocked:true,disabledNoDispatch:true,paidCalls:0}));
 }
}finally{if(gate&&gate.exitCode===null){gate.stdin.end('\n');await Promise.race([once(gate,'exit'),new Promise(r=>setTimeout(()=>{gate.kill('SIGKILL');r();},3000))]);}store?.database().close();rmSync(dir,{recursive:true,force:true});}
